import type { EdielDirection } from '@/lib/ediel/types'
import type { EdielFileEngineMode, ParsedEdielFile } from '@/lib/ediel/fileEngine'
import { resolveCanonicalOutboundVersion, resolveCanonicalInboundAcceptedVersions } from '@/lib/ediel/core/versionRegistry'

// The file importer must pass the actual payload into the same source-bound
// operational selector as every other caller, never a route/version fallback.
export async function withFileVersionValidation(params: {
  parsed: ParsedEdielFile;
  direction: EdielDirection;
  mode: EdielFileEngineMode;
  rawPayload: string;
}) {
  const report = {
    ...(params.parsed.validationReport ?? {}),
  } as Record<string, unknown>;

  const warnings = Array.isArray(report.warnings) ? [...report.warnings] : [];
  const errors = Array.isArray(report.errors) ? [...report.errors] : [];

  let resolvedVersion: string | null = params.parsed.messageVersion;
  let acceptedVersions: string[] = [];

  if (params.direction === "outbound") {
    resolvedVersion = await resolveCanonicalOutboundVersion({
      rawPayload: params.rawPayload,
      family: params.parsed.messageFamily,
      code: params.parsed.messageCode,
      standard: params.parsed.messageStandard,
      fallback: params.parsed.messageVersion,
      environment: params.mode === "production_dry_run" ? "production" : "test",
    });

    if (
      params.parsed.messageVersion &&
      resolvedVersion &&
      params.parsed.messageVersion !== resolvedVersion
    ) {
      warnings.push(
        `Filens version ${params.parsed.messageVersion} skiljer sig från runtime-version ${resolvedVersion}.`,
      );
    }
  } else {
    const acceptedVersionRows = await resolveCanonicalInboundAcceptedVersions({
      rawPayload: params.rawPayload,
      family: params.parsed.messageFamily,
      code: params.parsed.messageCode,
      standard: params.parsed.messageStandard,
    });

    acceptedVersions = acceptedVersionRows
      .map((row) => row.version_code)
      .filter(
        (versionCode): versionCode is string =>
          typeof versionCode === "string" && versionCode.length > 0,
      );

    if (
      params.parsed.messageVersion &&
      acceptedVersions.length > 0 &&
      !acceptedVersions.includes(params.parsed.messageVersion)
    ) {
      errors.push(
        `Inbound version ${params.parsed.messageVersion} är inte accepterad. Accepterade versioner: ${acceptedVersions.join(", ")}.`,
      );
    }
  }

  return {
    resolvedVersion,
    validationReport: {
      ...report,
      ok: errors.length === 0,
      warnings,
      errors,
      resolvedVersion,
      acceptedVersions,
    },
  };
}

import type { CreateEdielMessageInput } from '@/lib/ediel/types'
import { resolveCanonicalInboundAcceptedVersions } from '@/lib/ediel/core/versionRegistry'
import { AperakSourceProfileError } from '@/lib/ediel/rulebook/aperakSourceProfile'

/** Record a version check, not an ACK disposition or permission to mutate data.
 * Unmatched/invalid incoming profiles remain available for protected review. */
export async function withAcceptedInboundVersions(input: CreateEdielMessageInput): Promise<CreateEdielMessageInput> {
  const date = typeof input.messageReceivedAt === 'string' ? input.messageReceivedAt.slice(0, 10) : null
  const source = input.parsedPayload?.canonicalSourceMessageFamily
  let acceptedVersionCodes: string[] = []
  let profileError: string | null = null
  try {
    const accepted = await resolveCanonicalInboundAcceptedVersions({
      family: input.messageFamily, code: String(input.messageCode), standard: input.messageStandard,
      rawPayload: input.rawPayload, sourceMessageFamily: typeof source === 'string' ? source : null, date,
    })
    acceptedVersionCodes = accepted.map((row) => row.version_code)
  } catch (error) {
    if (!(error instanceof AperakSourceProfileError)) throw error
    profileError = error.message
  }
  const currentVersion = typeof input.messageVersion === 'string' ? input.messageVersion : null
  const versionAccepted = !profileError && (currentVersion === null
    ? acceptedVersionCodes.length === 0 : acceptedVersionCodes.includes(currentVersion))
  return {
    ...input,
    validationReport: {
      ...(input.validationReport ?? {}),
      acceptedInboundVersions: acceptedVersionCodes,
      inboundVersionAccepted: versionAccepted,
      inboundVersionCheckDate: date ?? new Date().toISOString().slice(0, 10),
      inboundVersionProfileError: profileError,
    },
  }
}

