import { AperakSourceProfileError } from '@/lib/ediel/rulebook/aperakSourceProfile'
import {
  resolveInboundAcceptedVersionsRuntimeFromRegistry,
  resolveOutboundMessageVersionRuntimeFromRegistry,
  type ResolveMessageVersionInput,
  type ResolvedVersionWindow,
} from '@/lib/ediel/core/versionRegistry'

export type VersionDisplayWindow = ResolvedVersionWindow & {
  requiresSourceProfile: boolean
  availableSourceProfiles?: readonly string[]
  sourceProfileError?: string
}

/** Read-only UI projection. Missing source context is not a default profile,
 * an accepted version, or readiness permission for any operational caller. */
export async function resolveMessageVersionCatalogue(input: ResolveMessageVersionInput): Promise<{
  outbound: VersionDisplayWindow
  inbound: VersionDisplayWindow
}> {
  try {
    const [outbound, inbound] = await Promise.all([
      resolveOutboundMessageVersionRuntimeFromRegistry(input),
      resolveInboundAcceptedVersionsRuntimeFromRegistry(input),
    ])
    return {
      outbound: { ...outbound, requiresSourceProfile: false },
      inbound: { ...inbound, requiresSourceProfile: false },
    }
  } catch (error) {
    // Only a known APERAK profile-selection failure can become a UI diagnostic.
    // DB failures and unsupported unrelated families remain real errors.
    if (!(error instanceof AperakSourceProfileError)) throw error
    const empty = (): VersionDisplayWindow => ({
      selectedVersion: null, currentVersion: null, previousVersion: null,
      acceptedVersions: [], selectedRule: null, currentRule: null, previousRule: null,
      requiresSourceProfile: true, availableSourceProfiles: ['PRODAT', 'UTILTS'],
      sourceProfileError: error.message,
    })
    return { outbound: empty(), inbound: empty() }
  }
}

